#include <zephyr/kernel.h>
#include <zephyr/sys/heap.h>
#include <zephyr/sys/util.h>
#include <zephyr/toolchain.h>
#include <string.h>

#include "heap_internal.h"

#define LOG_LEVEL CONFIG_HEAP_MEM_POOL_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(heap);

/*
 * The heap implementation uses a set of buckets, where each bucket contains a
 * doubly-linked list of free chunks of a specific size range. The smallest
 * bucket contains chunks of size Z_HEAP_CHUNK_MIN_SIZE. Each subsequent bucket
 * contains chunks that are twice the size of the previous bucket's chunks.
 *
 * Chunks are always aligned to Z_HEAP_CHUNK_ALIGN_UNIT.
 *
 * A chunk consists of a header (struct heap_chunk) followed by the user data.
 * The size of the chunk includes the header.
 *
 * The heap is managed as a single contiguous block of memory. When a chunk is
 * freed, it is merged with adjacent free chunks to form larger free chunks.
 *
 * The heap structure (struct k_heap) contains the heap metadata, including the
 * array of free lists (buckets) and pointers to the start and end of the heap
 * memory region.
 */

/*
 * The minimum chunk size is 16 bytes (Z_HEAP_CHUNK_MIN_SIZE).
 * The alignment unit is 8 bytes (Z_HEAP_CHUNK_ALIGN_UNIT).
 *
 * The chunk header (struct heap_chunk) is 8 bytes.
 * So, a chunk of size 16 bytes has 8 bytes for header and 8 bytes for data.
 */

/*
 * Helper to get the aligned size of a chunk, including the header.
 * The user-requested size is rounded up to the nearest Z_HEAP_CHUNK_ALIGN_UNIT.
 * Then, Z_HEAP_CHUNK_HEADER_SIZE is added to get the total chunk size.
 * Finally, the total size is rounded up to Z_HEAP_CHUNK_MIN_SIZE if it's smaller.
 */
#define Z_HEAP_CHUNK_ALIGNED_SIZE(size) 
	MAX(Z_HEAP_CHUNK_MIN_SIZE, 
	    ROUND_UP(size + Z_HEAP_CHUNK_HEADER_SIZE, Z_HEAP_CHUNK_ALIGN_UNIT))

/*
 * Convert a chunk size to a bucket index.
 * The buckets are sized exponentially: 16, 32, 64, ...
 * The index is calculated based on the logarithm base 2 of the size, shifted.
 * The last bucket is for chunks that are too large for the other buckets.
 */
static inline int _heap_size_to_idx(size_t size)
{
	size_t aligned_size = Z_HEAP_CHUNK_ALIGNED_SIZE(size);
	int idx = (aligned_size - Z_HEAP_CHUNK_MIN_SIZE) / Z_HEAP_CHUNK_ALIGN_UNIT;

	/* The last bucket is for chunks that are too large for the other
	 * buckets. Ensure the index does not exceed the maximum valid bucket index.
	 */	
	if (idx >= CONFIG_HEAP_MEM_POOL_NUM_BUCKETS) {
		idx = CONFIG_HEAP_MEM_POOL_NUM_BUCKETS - 1;
	}

	return idx;
}

/*
 * Get the next chunk in memory.
 */
static inline struct heap_chunk *_heap_chunk_next(struct k_heap *h,
						  struct heap_chunk *chunk)
{
	struct heap_chunk *next = (struct heap_chunk *)((uint8_t *)chunk + chunk->size);

	/* If the calculated next chunk goes beyond the heap's end, return the end sentinel. */
	if (next > h->end_chunk) {
		return h->end_chunk;
	}
	return next;
}

/*
 * Get the previous chunk in memory.
 */
static inline struct heap_chunk *_heap_chunk_prev(struct k_heap *h,
						  struct heap_chunk *chunk)
{
	ARG_UNUSED(h);

	if (chunk->prev_size == 0) {
		return NULL; /* No previous chunk or it's the first chunk */
	}
	return (struct heap_chunk *)((uint8_t *)chunk - chunk->prev_size);
}

/*
 * Check if a chunk is free.
 */
static inline bool _heap_chunk_is_free(struct heap_chunk *chunk)
{
	return (chunk->flags & HEAP_CHUNK_USED) == 0;
}

/*
 * Link a free chunk into its appropriate bucket list.
 */
static void _heap_chunk_link(struct k_heap *h, struct heap_chunk *chunk)
{
	int idx = _heap_size_to_idx(chunk->size);

	__ASSERT_NO_MSG(idx < CONFIG_HEAP_MEM_POOL_NUM_BUCKETS);

	sys_dlist_append(&h->free_list[idx], &chunk->node);
}

/*
 * Unlink a free chunk from its bucket list.
 */
static void _heap_chunk_unlink(struct k_heap *h, struct heap_chunk *chunk)
{
	int idx = _heap_size_to_idx(chunk->size);

	__ASSERT_NO_MSG(idx < CONFIG_HEAP_MEM_POOL_NUM_BUCKETS);

	sys_dlist_remove(&chunk->node);
}

/*
 * Merge two adjacent free chunks.
 * The 'right' chunk is merged into the 'left' chunk.
 */
static void _heap_chunk_merge(struct heap_chunk *left, struct heap_chunk *right)
{
	left->size += right->size;
	_heap_chunk_next(NULL, left)->prev_size = left->size;
}

/*
 * Split a chunk into two: one for the requested size, and the remainder as a
 * new free chunk.
 */
static struct heap_chunk *_heap_chunk_split(struct k_heap *h,
					     struct heap_chunk *chunk,
					     size_t size)
{
	struct heap_chunk *new_chunk;
	size_t new_size = chunk->size - size;

	/* The new chunk must be at least Z_HEAP_CHUNK_MIN_SIZE */
	__ASSERT_NO_MSG(new_size >= Z_HEAP_CHUNK_MIN_SIZE);

	chunk->size = size;

	new_chunk = (struct heap_chunk *)((uint8_t *)chunk + size);
	new_chunk->size = new_size;
	new_chunk->prev_size = size;
	new_chunk->flags = 0; /* Mark as free */

	/* Update the prev_size of the chunk after new_chunk */
	_heap_chunk_next(h, new_chunk)->prev_size = new_size;

	_heap_chunk_link(h, new_chunk);

	return chunk;
}

void k_heap_init(struct k_heap *h, void *heap_mem, size_t heap_size)
{
	__ASSERT_NO_MSG(heap_mem != NULL);
	__ASSERT_NO_MSG(heap_size >= Z_HEAP_CHUNK_MIN_SIZE + Z_HEAP_CHUNK_HEADER_SIZE);
	__ASSERT_NO_MSG(IS_ALIGNED(heap_mem, Z_HEAP_CHUNK_ALIGN_UNIT));

	h->heap = heap_mem;
	h->heap_size = heap_size;
	h->end_chunk = (struct heap_chunk *)((uint8_t *)heap_mem + heap_size);

	for (int i = 0; i < CONFIG_HEAP_MEM_POOL_NUM_BUCKETS; i++) {
		sys_dlist_init(&h->free_list[i]);
	}

	/* Initialize the first (and only) chunk as free and covering the entire heap. */
	struct heap_chunk *first_chunk = (struct heap_chunk *)heap_mem;
	first_chunk->size = heap_size;
	first_chunk->prev_size = 0; /* No previous chunk */
	first_chunk->flags = 0; /* Mark as free */

	/* The chunk after the first_chunk is the end_chunk. Set its prev_size. */
	h->end_chunk->prev_size = heap_size;

	_heap_chunk_link(h, first_chunk);

	LOG_DBG("Heap initialized: %p, size %zu", heap_mem, heap_size);
}

void *k_heap_alloc(struct k_heap *h, size_t size, k_timeout_t timeout)
{
	struct heap_chunk *chunk = NULL;
	size_t aligned_size = Z_HEAP_CHUNK_ALIGNED_SIZE(size);

	if (aligned_size > h->heap_size) {
		LOG_ERR("Allocation size %zu exceeds heap size %zu", size, h->heap_size);
		return NULL;
	}

	k_spinlock_key_t key = k_spin_lock(&h->lock);

	/* Iterate through buckets to find a suitable free chunk. */
	for (int i = _heap_size_to_idx(size); i < CONFIG_HEAP_MEM_POOL_NUM_BUCKETS; i++) {
		sys_dlist_peek_head_for_each_node(h->free_list[i], chunk, node) {
			if (chunk->size >= aligned_size) {
				_heap_chunk_unlink(h, chunk);
				goto found_chunk;
			}
		}
	}

	/* No suitable chunk found. */
	LOG_DBG("No free chunk of size %zu found", size);
	k_spin_unlock(&h->lock, key);
	return NULL;

found_chunk:
	/* If the chunk is large enough to split, split it. */
	if ((chunk->size - aligned_size) >= Z_HEAP_CHUNK_MIN_SIZE) {
		chunk = _heap_chunk_split(h, chunk, aligned_size);
	}

	chunk->flags |= HEAP_CHUNK_USED; /* Mark as used */

	k_spin_unlock(&h->lock, key);

	LOG_DBG("Allocated %zu bytes at %p (chunk %p)", size, (uint8_t *)chunk + Z_HEAP_CHUNK_HEADER_SIZE, chunk);
	return (uint8_t *)chunk + Z_HEAP_CHUNK_HEADER_SIZE;
}

void k_heap_free(struct k_heap *h, void *ptr)
{
	if (ptr == NULL) {
		return;
	}

	struct heap_chunk *chunk = (struct heap_chunk *)((uint8_t *)ptr - Z_HEAP_CHUNK_HEADER_SIZE);

	__ASSERT_NO_MSG(chunk >= (struct heap_chunk *)h->heap && chunk < h->end_chunk);
	__ASSERT_NO_MSG(IS_ALIGNED(chunk, Z_HEAP_CHUNK_ALIGN_UNIT));
	__ASSERT_NO_MSG(chunk->flags & HEAP_CHUNK_USED); /* Must be a used chunk */

	k_spinlock_key_t key = k_spin_lock(&h->lock);

	chunk->flags &= ~HEAP_CHUNK_USED; /* Mark as free */

	/* Try to merge with previous chunk if it's free. */
	struct heap_chunk *prev_chunk = _heap_chunk_prev(h, chunk);
	if (prev_chunk != NULL && _heap_chunk_is_free(prev_chunk)) {
		_heap_chunk_unlink(h, prev_chunk);
		_heap_chunk_merge(prev_chunk, chunk);
		chunk = prev_chunk;
	}

	/* Try to merge with next chunk if it's free. */
	struct heap_chunk *next_chunk = _heap_chunk_next(h, chunk);
	if (next_chunk != h->end_chunk && _heap_chunk_is_free(next_chunk)) {
		_heap_chunk_unlink(h, next_chunk);
		_heap_chunk_merge(chunk, next_chunk);
	}

	_heap_chunk_link(h, chunk);

	k_spin_unlock(&h->lock, key);

	LOG_DBG("Freed %zu bytes at %p (chunk %p)", chunk->size - Z_HEAP_CHUNK_HEADER_SIZE, ptr, chunk);
}

size_t k_heap_bytes_free(struct k_heap *h)
{
	size_t total_free = 0;
	k_spinlock_key_t key = k_spin_lock(&h->lock);

	for (int i = 0; i < CONFIG_HEAP_MEM_POOL_NUM_BUCKETS; i++) {
		sys_dlist_peek_head_for_each_node(h->free_list[i], struct heap_chunk, node) {
			total_free += chunk->size;
		}
	}

	k_spin_unlock(&h->lock, key);

	return total_free;
}

size_t k_heap_bytes_used(struct k_heap *h)
{
	return h->heap_size - k_heap_bytes_free(h);
}
